from pathlib import Path
p=Path(__file__).resolve().parents[1]/'outputs/yidaizhang-local/public/finance-ui.js'
s=p.read_text(encoding='utf-8')
start=s.index('function renderAssets()')
end=s.index('function renderInventory()',start)
s=s[:start]+'''function renderAssets(){return actionbar('固定资产卡片',button('新增固定资产','new-asset','',true)+button('计提本月折旧','depreciate'),'购置次月起直线折旧，残值不计折旧；购置、折旧和清理均生成凭证。')+table(['资产名称','购置日期','开始折旧','原值','残值','折旧月数','累计折旧','账面净值','状态','操作'],book.assets.map(a=>`<tr><td>${h(a.name)}</td><td>${h(a.purchase_date)}</td><td>${h(a.start_period)}</td><td class="number">${money(a.cost_fen)}</td><td class="number">${money(a.residual_fen)}</td><td>${a.life_months}</td><td class="number">${money(a.accumulated_fen)}</td><td class="number">${money(a.net_fen)}</td><td>${statusBadge(({active:'使用中',disposed:'已清理',cancelled:'已撤销购置'})[a.status]||a.status,a.status==='active'?'success':'')}</td><td class="book-row-actions">${button('折旧明细','asset-detail',`data-id="${a.id}"`)}${a.status==='active'?button('资产清理','dispose-asset',`data-id="${a.id}"`):''}</td></tr>`));}
''' +s[end:]
start=s.index('function renderInventory()')
end=s.index('function renderPayroll()',start)
s=s[:start]+'''function renderInventory(){return actionbar('库存商品',button('新增商品','new-item','',true)+button('入库 / 出库','inventory-move'),'采用移动加权平均成本；不允许负库存，已发生后续移动的商品不接受倒序入账。')+table(['商品编码','商品名称','单位','结存数量','结存成本','存货科目','成本科目'],book.inventory_items.map(i=>`<tr><td>${h(i.sku)}</td><td>${h(i.name)}</td><td>${h(i.unit)}</td><td class="number">${h(i.quantity)}</td><td class="number">${money(i.value_fen)}</td><td>${h(i.inventory_account)}</td><td>${h(i.cost_account)}</td></tr>`))+'<div class="book-section-gap"></div>'+actionbar('库存出入库记录','')+table(['日期','商品','方向','数量','成本金额','状态','关联凭证'],book.inventory_movements.map(m=>`<tr class="${m.status==='void'?'book-void':''}"><td>${h(m.date)}</td><td>${h(m.item_name||m.item_id)}</td><td>${statusBadge(m.direction==='in'?'入库':'出库',m.direction==='in'?'success':'pending')}</td><td class="number">${h(m.quantity)}</td><td class="number">${money(m.amount_fen)}</td><td>${m.status==='void'?'已撤回':'有效'}</td><td>${m.voucher_id?`#${m.voucher_id}`:'—'}</td></tr>`));}
''' +s[end:]
start=s.index('function renderPayroll()')
end=s.index('function renderJournals()',start)
s=s[:start]+'''function renderPayroll(){let gross=0,net=0;book.payroll.forEach(p=>{gross+=p.gross_fen;net+=p.net_fen;});return actionbar('工资表',button('新增工资记录','new-payroll','',true)+button('生成工资计提凭证','post-payroll')+button('登记工资发放','pay-payroll'),'个税、社保和其他扣款由会计录入；系统计算实发，不自动推算个人所得税。')+table(['所属期间','员工姓名','应发工资','代扣个税','个人社保','其他扣款','实发工资','计提凭证','发放凭证','操作'],book.payroll.map(p=>`<tr><td>${h(p.period)}</td><td>${h(p.employee_name)}</td>${['gross_fen','withheld_tax_fen','social_fen','other_deduction_fen','net_fen'].map(k=>`<td class="number">${money(p[k])}</td>`).join('')}<td>${p.voucher_id?`#${p.voucher_id}`:statusBadge('待计提','pending')}</td><td>${p.payment_voucher_id?`#${p.payment_voucher_id}`:'未登记发放'}</td><td>${!p.voucher_id?button('删除重录','delete-payroll',`data-id="${p.id}"`):'需先撤回来源凭证后纠错'}</td></tr>`))+`<p class="book-totals">应发合计 ${money(gross)}　实发合计 ${money(net)}</p><p class="muted">计提和实发分别生成凭证。实际转账及缴纳须在外部办理；发放时生成的代扣负债，可在资金日记账继续登记缴纳。</p>`;}
''' +s[end:]
s=s.replace("case 'dispose-asset':return disposeModal(ctx,id);", "case 'dispose-asset':return disposeModal(ctx,id);\n    case 'asset-detail':return assetDetail(ctx,id);")
s=s.replace("case 'new-payroll':return payrollModal(ctx);", "case 'new-payroll':return payrollModal(ctx);\n    case 'delete-payroll':{const p=book.payroll.find(x=>x.id===id);return confirm(ctx,'删除未计提工资',`删除 ${p.employee_name} 的未计提工资后可重新录入，操作保留审计。`,()=>save(ctx,`${base()}/payroll/${id}`,{version:p.version},'DELETE'));}")
s += '''
function assetDetail(ctx,id){const a=book.assets.find(x=>x.id===id),records=a.depreciations||[],zeros=records.filter(r=>!r.voucher_id);const content=`<p>${h(a.name)} · ${h(book.period)}以前的折旧记录</p>${table(['期间','折旧额','关联凭证'],records.map(r=>`<tr><td>${h(r.period)}</td><td class="number">${money(r.amount_fen)}</td><td>${r.voucher_id?'#'+r.voucher_id:'0分折旧，无凭证'}</td></tr>`),'暂无折旧记录')}<p class="muted">非零折旧纠错请到凭证管理取消审核并撤回来源凭证；需从最近的折旧开始。历史及审计保留。</p>${zeros.length?`<div class="form-grid">${selectField('period','撤回0分折旧记录',zeros.map(r=>[r.period,r.period]))}${field('reason','撤回原因','text','','required')}</div>`:''}`;return ctx.modal('资产折旧明细',content,zeros.length?async form=>save(ctx,`${base()}/assets/${id}/depreciations/${form.elements.period.value}/withdraw`,{version:a.version,reason:form.elements.reason.value}):undefined);}
'''
p.write_text(s,encoding='utf-8')
